168	      } else {
169	        setStatus("error");
170	      }
171	
172	      // Persist only a location the user actually supplied — including the
173	      // silent refresh, which is the point of keeping the record fresh. Never
174	      // for the profile/default fallback: there is nothing new to write.
175	      if (city && res.status !== "error") {
176	        saveLocation({ ...city, timezone: res.weather.timezone }).catch(() => {
177	          /* non-fatal — never disturb the looks */
178	        });
179	      }
180	    },
181	    [city, applyPendingGeo],
182	  );
183	
184	  // Reads today's stored set. Switching occasion runs this again,
185	  // but the action answers from the database — no AI call, no spend.
186	  // The morning seed: predict the occasion BEFORE the first generate, so the
187	  // generate effect reads the right stored set and runs ONCE. Predicting is
188	  // cheap (no AI/weather). The generate effect is gated on `seeded` below, so
189	  // it never fires for the placeholder "everyday" and then again for the
190	  // prediction — that would spend two AI calls on a fresh day.
191	  useEffect(() => {
192	    let cancelled = false;
193	
194	    // Synchronous, before the async prediction resolves — so the generate effect
195	    // (gated on `seeded`) runs once, against the restored occasion.
196	    const sp = new URLSearchParams(window.location.search);
197	    const restoredOccasion = OCCASIONS.find((o) => o === sp.get("occasion")) ?? null;
198	    urlOccasionRef.current = restoredOccasion;
199	    desiredLookRef.current = Number(sp.get("look")) || null;
200	    if (restoredOccasion) setOccasion(restoredOccasion);
201	
202	    predictDefaultOccasion()
203	      .then(({ occasion: predicted, reason: why }) => {
204	        if (cancelled) return;
205	        // predictedRef is set either way — it is the baseline every override is
206	        // logged against, and a restored URL occasion is not a fresh override
207	        // (the user already tapped it once, and it was logged then).
208	        predictedRef.current = predicted;
209	        if (urlOccasionRef.current) setReason(defaultReason(urlOccasionRef.current));
210	        else {
211	          setReason(why);
212	          setOccasion(predicted);
213	        }
214	      })
215	      .finally(() => {
216	        // Release the gate even if prediction fails — looks still load against
217	        // the "everyday" fallback.
218	        if (!cancelled) setSeeded(true);
219	      });
220	    return () => {
221	      cancelled = true;
222	    };
223	  }, []);
224	
225	  useEffect(() => {
226	    if (!seeded) return; // wait for the prediction, so generate runs once
227	    let cancelled = false;
228	    setStatus("loading");
229	    generate({ occasion, formality, lean, city: city ?? undefined }).then((res) => {
230	      if (cancelled) return;
231	      applyResult(res);
232	    });
233	    return () => {
234	      cancelled = true;
235	    };
236	  }, [seeded, occasion, formality, lean, city, nonce, applyResult]);
237	
238	  /**
239	   * The only path that spends an AI call on a day already answered.
240	   *
241	   * Deliberately a direct call rather than an effect dependency: a flag routed
242	   * through the effect can still be in flight when the user switches occasion,
243	   * and would then regenerate that occasion too.
244	   */
245	  const regenerate = useCallback(() => {
246	    // A fresh set starts at 01, and the remembered index may not even exist.
247	    desiredLookRef.current = null;
248	    writeParams({ look: null });
249	    setStatus("loading");
250	    generate({ occasion, formality, lean, city: city ?? undefined, regenerate: true }).then(
251	      applyResult,
252	    );
253	  }, [occasion, formality, lean, city, applyResult, writeParams]);
254	
255	  return (
256	    <StylistView
257	      status={status}
258	      weather={weather}
259	      looks={looks}
260	      selectedLook={selectedLook}
261	      occasion={occasion}
262	      cities={cities}
263	      refineOpen={refineOpen}
264	      missing={missing}
265	      locating={locating}
266	      geoError={geoError}
267	      reason={reason}
268	      onOccasion={(o) => {
269	        setOccasion(o);
270	        setReason(defaultReason(o));
271	        // A new occasion is a new set of looks — drop the remembered index.
272	        desiredLookRef.current = null;
273	        writeParams({ occasion: o, look: null });
274	        // A tap that departs from the prediction is the flywheel signal for the
275	        // future learner. Fire-and-forget — it must never disturb the looks.
276	        if (o !== predictedRef.current) {
277	          logOccasionOverride({ predicted: predictedRef.current, chosen: o }).catch(() => {});
278	        }
279	      }}
280	      onOpenRefine={() => setRefineOpen(true)}
281	      onCloseRefine={() => setRefineOpen(false)}
282	      onRefineApply={({ formality: f, lean: c }) => {
283	        setFormality(f);
284	        setLean(c);
285	        setRefineOpen(false);
286	      }}
287	      onCityChange={(c) => {
288	        userChoseRef.current = true;
289	        pendingGeoRef.current = null;
290	        setCity({ lat: c.lat, lon: c.lon, label: c.name, source: "city" });
291	      }}
292	      onCitySearch={(q) => {
293	        if (q.trim().length < 2) return;
294	        searchCities(q).then(setCities);
295	      }}
296	      onUseMyLocation={geoSupported ? useMyLocation : undefined}
297	      onSelectLook={(i) => {
298	        desiredLookRef.current = i || null;
299	        setSelectedLook(i);
300	        writeParams({ look: i === 0 ? null : String(i) });
301	      }}
302	      onRetry={() => setNonce((n) => n + 1)}
303	      onRegenerate={regenerate}
304	    />
305	  );
306	}
